import{_ as t,C as r,o as i,c as s,a5 as a,E as n}from"./chunks/framework.BwlBv862.js";const b=JSON.parse('{"title":"诊断失败的操作","description":"","frontmatter":{"title":"诊断失败的操作","docId":"user.preferences.troubleshooting","translationKey":"user.preferences.troubleshooting","locale":"zh","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"40d8c5706363baa28e4114397696c8c2adb320843271a00efb3772be0322d5e2","translationRevision":"732ff8dabf3951e283cafea2ede53a2d1e9354332fb56980ac6c5b3b918c4f2b","order":30},"headers":[],"relativePath":"zh/user/preferences/troubleshooting.md","filePath":"zh/user/preferences/troubleshooting.md","lastUpdated":1794611623000}'),l={name:"zh/user/preferences/troubleshooting.md"};function d(c,e,h,u,p,f){const o=r("DemoFrame");return i(),s("div",null,[e[0]||(e[0]=a('<h1 id="diagnose-a-failed-operation" tabindex="-1">诊断失败的操作 <a class="header-anchor" href="#diagnose-a-failed-operation" aria-label="Permalink to &quot;诊断失败的操作 {#diagnose-a-failed-operation}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>定位故障组件，收集有用报告，并避免反复触发效果。你需要应用版本、故障大致时间及尝试的操作。重置或替换数据前，请保留<a href="./backups.html">备份</a>。</p><h2 id="inspect-the-nearest-evidence" tabindex="-1">查看最直接的证据 <a class="header-anchor" href="#inspect-the-nearest-evidence" aria-label="Permalink to &quot;查看最直接的证据 {#inspect-the-nearest-evidence}&quot;">​</a></h2><ol><li>阅读故障位置的行内错误。使用其诊断状态操作，或打开 <strong>诊断</strong> 查看相关条目。</li><li>按来源、级别或文本筛选。有用的来源包括 LIVE、监控、插件、账户、同步、更新、传输、目录、安装与协作。</li><li>选择相关条目，保留时间、代码、请求/实体标识符及简短说明。有详情时展开查看。</li><li>复制筛选后的诊断信息或导出文本报告。剪贴板/导出失败时，使用显示的备用文本。分享前检查并移除私有令牌、Cookie、邀请链接及个人内容。</li><li>提供简短复现步骤：页面、所选主播/配置/插件、执行操作、预期结果和实际结果。说明发生在更新前还是更新后。</li></ol><h2 id="isolate-common-failures" tabindex="-1">隔离常见故障 <a class="header-anchor" href="#isolate-common-failures" aria-label="Permalink to &quot;隔离常见故障 {#isolate-common-failures}&quot;">​</a></h2><p>事件流为空时，清除搜索与筛选、恢复滚动并确认<a href="./../live/connections.html">连接</a>。暂停滚动不等于断线。显示丢失提示不能证明积分或统计也丢失了同一事件。</p><p>自动化没有运行记录时，检查当前配置、事件/操作启用状态、触发器、筛选字段路径及冷却时间。改变效果前先查看运行历史。<strong>运行测试</strong> 可能执行音频、HTTP、积分及插件操作。</p><p>插件故障请阅读安装作业或连接错误。Cloud 故障请检查账户状态及受影响区域，不要更换 TikTok Cookie。叠加层请检查网关状态和源配置。更新无法安装时，请使用<a href="./../updates.html">手动更新指南</a>。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;预期结果与状态 {#expected-result-and-status}&quot;">​</a></h2><p>诊断筛选、复制及文本导出均可使用。打包应用还需要其 Web 资源和平台运行时。Linux 上检查受支持的 GTK/WebKitGTK 环境及 X11/XWayland 会话；Windows 上检查 WebView2。安装范围见<a href="./../requirements.html">系统要求</a>。</p><h2 id="recovery" tabindex="-1">恢复方法 <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;恢复方法 {#recovery}&quot;">​</a></h2><p>修正具体原因后再重试。修订冲突时，重新加载并审查当前保存状态。远程命令未确认时，先检查日志/状态再发送另一个命令：超时也可能发生在效果已成功之后。启动失败时，报告安装包、版本及启动日志，不要直接删除数据目录。</p>',13)),n(o,{scenario:"diagnostics",locale:"zh",tour:"diagnostics",title:"演示：诊断"}),e[1]||(e[1]=a('<h2 id="operational-details" tabindex="-1">运行细节 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;运行细节 {#operational-details}&quot;">​</a></h2><p>Diagnostics 是内存中的界面日志，上限为 2,000 条或 2 MiB；五秒内的重复项会合并。界面初始显示 100 条，导出包含所有匹配筛选的条目，而<strong>清空</strong>会删除整个日志。关闭、重启、清空或切换/退出已知 Cloud 账户前，请先复制或导出证据；这些账户切换会清空该界面历史。</p><p>窗口无法打开时，查看原生日志 <code>tiktools.log</code>（控制器模式为 <code>controller.log</code>）：Windows 默认在 <code>%LOCALAPPDATA%/TikTools/logs</code>，Linux 在 <code>${XDG_DATA_HOME:-~/.local/share}/TikTools/logs</code>。<code>TIKTOOLS_HOME</code> 改变根目录，<code>TIKTOOLS_LOG_DIR</code> 覆盖日志目录。日志初始化自身失败时文件可能不存在，请保留可获得的终端/启动错误。原生日志不保证具备界面脱敏，分享前务必人工检查。</p>',3))])}const m=t(l,[["render",d]]);export{b as __pageData,m as default};
